package antigravity

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// v2SpikeNoteRequest is the draft request sent to the agent asking it to write a turn note.
// This is the X1 experiment version; wording will be tuned in X2.
const v2SpikeNoteRequest = `repo-memory: before you stop, write a memory note for this repository. Cover only what happened since your last memory note, or since the start of the conversation if there is none. Don't continue the task, don't call tools, and don't repeat your previous answer.

Record only what a capable engineer new to this code would get wrong without being told:
- decisions, with why and the alternatives rejected;
- approaches that failed, and why;
- error → cause → fix;
- rules that must hold;
- how external tools or systems behaved;
- procedures you verified;
- open issues, with what would close them.

Leave out anything the code or docs already say, progress narration, plans you didn't carry out, and anything that only repeats repo-memory notes shown to you in this conversation.

Reply with one repo-memory-note block in the format below, or the single word NONE.

` + "```" + `repo-memory-note
- type: <decision|ruled-out|failure-signature|invariant|external-behaviour|procedure|open-issue|convention>
  title: <short title>
  why: <explanation>
  do: <what to do about it, if applicable>
  anchors: [relevant/file/paths]
  evidence: <how you know>
` + "```"

// noteBlockRe matches a fenced repo-memory-note block in the agent's reply.
var noteBlockRe = regexp.MustCompile("(?s)```repo-memory-note\n(.*?)```")

// v2SpikeStopGate evaluates the v2 spike Stop gate conditions and returns:
// - continue: whether to send a continue response
// - request: the continue request string (only if continue is true)
// - note: the harvested note content (only on harvest pass)
// - success: whether harvest succeeded (only on harvest pass)
// - harvestErr: error description if harvest failed
//
// All v2 spike logic is gated behind REPO_MEMORY_V2_SPIKE=1.
func v2SpikeStopGate(payload *StopPayload, convID, transcriptPath, dataDir, repoID string) (continueResp bool, request string, note string, success bool, harvestErr string) {
	// Gate 0: v2 spike must be enabled
	if os.Getenv("REPO_MEMORY_V2_SPIKE") != "1" {
		return false, "", "", false, ""
	}

	fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Stop gate evaluating: convID=%s terminationReason=%q fullyIdle=%v executionNum=%d\n",
		convID, payload.TerminationReason, payload.FullyIdle, payload.ExecutionNum)

	// Gate 1: Must have a conversation ID
	if convID == "" {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Gate skip: no conversation ID\n")
		return false, "", "", false, ""
	}

	// ─── HARVEST PASS (executionNum >= 1) ───
	if payload.ExecutionNum >= 1 {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest pass: executionNum=%d\n", payload.ExecutionNum)
		note, success, harvestErr = v2SpikeHarvestNote(convID, transcriptPath, dataDir, repoID)
		return false, "", note, success, harvestErr
	}

	// ─── GATE PASS (executionNum == 0) ───

	// Gate 2: terminationReason must be NO_TOOL_CALL (case-insensitive)
	if !strings.EqualFold(payload.TerminationReason, "NO_TOOL_CALL") {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Gate skip: terminationReason=%q (want NO_TOOL_CALL)\n", payload.TerminationReason)
		return false, "", "", false, ""
	}

	// Gate 3: fullyIdle must be true
	if !payload.FullyIdle {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Gate skip: fullyIdle=false\n")
		return false, "", "", false, ""
	}

	// Gate 4: Must not be a subagent (has a parent conversation ID)
	if payload.ParentConversationID != "" {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Gate skip: subagent (parent=%s)\n", payload.ParentConversationID)
		return false, "", "", false, ""
	}

	// All gates passed — request a continue
	fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Gate PASSED: requesting continue for %s\n", convID)
	return true, v2SpikeNoteRequest, "", false, ""
}

// v2SpikeHarvestNote reads the transcript to find and extract the repo-memory-note
// block from the agent's response to our continue request.
func v2SpikeHarvestNote(convID, transcriptPath, dataDir, repoID string) (note string, success bool, harvestErr string) {
	if transcriptPath == "" {
		transcriptPath = findBrainTranscript(convID)
	}
	if transcriptPath == "" {
		return "", false, "no transcript path available"
	}

	// Read the transcript and find the last model response
	lastModelContent, err := v2SpikeReadLastModelResponse(transcriptPath)
	if err != nil {
		errMsg := fmt.Sprintf("reading transcript: %v", err)
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest error: %s\n", errMsg)
		return "", false, errMsg
	}

	if lastModelContent == "" {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest: no model response found in transcript\n")
		return "", false, "no model response found in transcript"
	}

	// Check for NONE response
	if strings.TrimSpace(lastModelContent) == "NONE" {
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest: agent replied NONE (no notable learnings)\n")
		return "NONE", true, ""
	}

	// Extract the repo-memory-note block
	matches := noteBlockRe.FindStringSubmatch(lastModelContent)
	if len(matches) < 2 {
		// Check if the response contains tool calls (failure case per §5.1)
		if strings.Contains(lastModelContent, "tool_calls") || strings.Contains(lastModelContent, "\"toolName\"") {
			errMsg := "agent made tool calls in response to note request (failure per §5.1)"
			fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest FAILURE: %s\n", errMsg)
			return "", false, errMsg
		}
		errMsg := "no repo-memory-note block found in agent response"
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest FAILURE: %s\n", errMsg)
		// Log the response for debugging (truncated)
		truncated := lastModelContent
		if len(truncated) > 500 {
			truncated = truncated[:500] + "..."
		}
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Agent response was: %s\n", truncated)
		return "", false, errMsg
	}

	noteContent := strings.TrimSpace(matches[1])
	fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Harvest SUCCESS: extracted note (%d bytes)\n", len(noteContent))

	// Write the note to the evidence store
	if writeErr := v2SpikeWriteNote(convID, noteContent, dataDir, repoID); writeErr != nil {
		errMsg := fmt.Sprintf("writing note to evidence store: %v", writeErr)
		fmt.Fprintf(os.Stderr, "[repo-memory v2-spike] Warning: %s\n", errMsg)
		// Still report success — the note was harvested even if storage failed
		return noteContent, true, errMsg
	}

	return noteContent, true, ""
}

// v2SpikeReadLastModelResponse reads the transcript and returns the content of the
// last PLANNER_RESPONSE step (the agent's response to our continue request).
func v2SpikeReadLastModelResponse(transcriptPath string) (string, error) {
	f, err := os.Open(transcriptPath)
	if err != nil {
		return "", err
	}
	defer f.Close()

	var lastModelContent string
	scanner := bufio.NewScanner(f)
	buf := make([]byte, 1024*1024)
	scanner.Buffer(buf, 50*1024*1024) // up to 50MB per line

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" || line == "CHECKPOINT" {
			continue
		}

		var step struct {
			Source   string          `json:"source"`
			Type    string          `json:"type"`
			Content string          `json:"content"`
			ToolCalls json.RawMessage `json:"tool_calls"`
		}
		if err := json.Unmarshal([]byte(line), &step); err != nil {
			continue
		}

		// Track the last model response
		if step.Source == "MODEL" && step.Type == "PLANNER_RESPONSE" && step.Content != "" {
			lastModelContent = step.Content
		}
	}

	if err := scanner.Err(); err != nil {
		return "", err
	}

	return lastModelContent, nil
}

// v2SpikeWriteNote writes a harvested turn note to the evidence store as a JSON file.
func v2SpikeWriteNote(convID, noteContent, dataDir, repoID string) error {
	noteDir := filepath.Join(dataDir, repoID, "evidence", "v2-spike-notes")
	if err := os.MkdirAll(noteDir, 0755); err != nil {
		return err
	}

	timestamp := time.Now().UTC().Format("20060102T150405Z")
	filename := fmt.Sprintf("%s_%s.json", timestamp, convID)
	notePath := filepath.Join(noteDir, filename)

	noteRecord := map[string]interface{}{
		"conversation_id": convID,
		"harvested_at":    time.Now().UTC().Format(time.RFC3339),
		"note_content":    noteContent,
		"experiment":      "X1-stop-continue",
	}

	data, err := json.MarshalIndent(noteRecord, "", "  ")
	if err != nil {
		return err
	}

	return os.WriteFile(notePath, data, 0644)
}

