func TestV2SpikeStopGate_HarvestOnSecondStop(t *testing.T) {
	t.Setenv("REPO_MEMORY_V2_SPIKE", "1")

	// Create a temp transcript with a model response containing a note block
	tmpDir := t.TempDir()
	transcriptPath := filepath.Join(tmpDir, "transcript_full.jsonl")

	// Write a transcript with the note response
	steps := []map[string]interface{}{
		{
			"step_index": 0,
			"source":     "USER_EXPLICIT",
			"type":       "USER_INPUT",
			"content":    "Please fix the bug",
		},
		{
			"step_index": 1,
			"source":     "MODEL",
			"type":       "PLANNER_RESPONSE",
			"content":    "I fixed the bug by updating the handler.",
		},
		{
			"step_index": 2,
			"source":     "SYSTEM",
			"type":       "SYSTEM_MESSAGE",
			"content":    "stop hook blocked termination due to reason: repo-memory note request",
		},
		{
			"step_index": 3,
			"source":     "MODEL",
			"type":       "PLANNER_RESPONSE",
			"content":    "```repo-memory-note\n- type: decision\n  title: Use handler pattern for bug fix\n  why: The handler pattern isolates the error handling from the business logic\n  do: Always wrap error-prone calls in the handler\n  anchors: [internal/handler.go]\n  evidence: Verified the fix resolves the race condition\n```",
		},
	}

	f, err := os.Create(transcriptPath)
	if err != nil {
		t.Fatal(err)
	}
	for _, step := range steps {
		data, _ := json.Marshal(step)
		f.Write(data)
		f.Write([]byte("\n"))
	}
	f.Close()

	dataDir := t.TempDir()
	repoID := "test-repo"
	os.MkdirAll(filepath.Join(dataDir, repoID, "evidence", "v2-spike-notes"), 0755)

	payload := &StopPayload{
		TerminationReason: "NO_TOOL_CALL",
		FullyIdle:         true,
		ExecutionNum:      1,
		ConversationID:    "test-conv-123",
	}

	cont, _, note, success, harvestErr := v2SpikeStopGate(payload, "test-conv-123", transcriptPath, dataDir, repoID)
	if cont {
		t.Error("expected continue=false on harvest pass")
	}
	if !success {
		t.Errorf("expected harvest success, got error: %s", harvestErr)
	}
	if note == "" {
		t.Error("expected non-empty harvested note")
	}
	if harvestErr != "" {
		t.Errorf("expected no harvest error, got: %s", harvestErr)
	}

	// Verify the note contains expected content
	if !containsString(note, "handler pattern") {
		t.Errorf("expected note to contain 'handler pattern', got: %s", note)
	}

	// Verify the note was written to the evidence store
	noteFiles, _ := filepath.Glob(filepath.Join(dataDir, repoID, "evidence", "v2-spike-notes", "*.json"))
	if len(noteFiles) == 0 {
		t.Error("expected note file to be written to evidence store")
	}
}

