func TestV2SpikeHandleStop_ContinueResponse(t *testing.T) {
	t.Setenv("REPO_MEMORY_V2_SPIKE", "1")

	// This tests the full HandleStop path returning a continue JSON response.
	// We need a fully enrolled workspace for HandleStopEvent to reach the v2 gate.
	// For a unit test, we test the response marshalling directly.
	result := &StopResult{
		V2Continue:        true,
		V2ContinueRequest: "Write a note please",
	}

	if !result.V2Continue {
		t.Error("expected V2Continue to be true")
	}

	resp := map[string]interface{}{
		"decision": "continue",
		"reason":   result.V2ContinueRequest,
	}
	out, err := json.Marshal(resp)
	if err != nil {
		t.Fatal(err)
	}

	var parsed map[string]string
	if err := json.Unmarshal(out, &parsed); err != nil {
		t.Fatal(err)
	}
	if parsed["decision"] != "continue" {
		t.Errorf("expected decision=continue, got %q", parsed["decision"])
	}
	if parsed["reason"] != "Write a note please" {
		t.Errorf("expected reason='Write a note please', got %q", parsed["reason"])
	}
}

func containsString(s, substr string) bool {
	return len(s) >= len(substr) && (s == substr || len(s) > 0 && stringContains(s, substr))
}

func stringContains(s, substr string) bool {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}

